'use strict';

// MODULES //

var floor = require( '@stdlib/math/base/special/floor' );


// MAIN //

/**
* Returns the number of Strassen–Winograd recursion levels performed for a given problem size.
*
* ## Notes
*
* -   Recursion continues while every dimension exceeds the cutoff and fewer than `levels` levels have been performed. Each level halves every dimension (rounding down).
*
* @private
* @param {NonNegativeInteger} M - number of rows in `op(A)` and `C`
* @param {NonNegativeInteger} N - number of columns in `op(B)` and `C`
* @param {NonNegativeInteger} K - number of columns in `op(A)` and rows in `op(B)`
* @param {PositiveInteger} cutoff - recursion cutoff
* @param {NonNegativeInteger} levels - maximum number of recursion levels
* @returns {NonNegativeInteger} number of recursion levels
*
* @example
* var d = depth( 1024, 1024, 1024, 64, 4 );
* // returns 4
*
* @example
* var d = depth( 100, 100, 100, 64, 4 );
* // returns 1
*/
function depth( M, N, K, cutoff, levels ) {
	var d = 0;
	while ( d < levels && M > cutoff && N > cutoff && K > cutoff ) {
		M = floor( M/2 );
		N = floor( N/2 );
		K = floor( K/2 );
		d += 1;
	}
	return d;
}


// EXPORTS //

module.exports = depth;
